def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Continue each diagonal pair of equal-colored cells outward,
    # stopping at the grid edge or at any non-background cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w):
                    continue
                if grid[r2][c2] != color:
                    continue

                for sr, sc, step in ((r, c, -1), (r2, c2, 1)):
                    rr, cc = sr + step * dr, sc + step * dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr += step * dr
                        cc += step * dc

    return out
